#include "shop_v1/client.h"

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    shop_v1_error error = {0};
    /* The client sends Crucible-Version: v1 on every request. */
    shop_v1_client_config config = shop_v1_client_defaults();
    config.endpoint = shop_v1_string_view(getenv("SHOP_ENDPOINT"));
    shop_v1_client *client = NULL;
    if (shop_v1_client_new(&config, &client, &error) != shop_v1_ok) {
        fprintf(stderr, "shop_v1_client_new: %s\n", error.message);
        return 1;
    }

    /* Sample values generated from the model's types and constraints. */
    shop_v1_models_count_items_input input = {0};
    shop_v1_models_count_items_input_set_shelf(&input, shop_v1_string_view("shelf"));

    shop_v1_operations_count_items_result result = {0};
    shop_v1_status status = shop_v1_operations_count_items(client, &input, NULL, NULL, &result, &error);
    if (status == shop_v1_ok) {
        printf("count: %lld\n", (long long)shop_v1_models_count_items_output_get_count(result.value));
    } else if (shop_v1_error_as_count_unavailable_exception(&result.base) != NULL) {
        shop_v1_string text = {0};
        const shop_v1_models_count_unavailable_exception *failure = shop_v1_error_as_count_unavailable_exception(&result.base);
        fprintf(stderr, "CountUnavailableException (HTTP %d)\n", result.base.response.status);
        text = shop_v1_models_count_unavailable_exception_get_message(failure);
        fprintf(stderr, "message: %.*s\n", (int)text.length, text.data);
    } else {
        fprintf(stderr, "CountItems failed: %s\n", error.message);
    }
    shop_v1_operations_count_items_result_free(&result);
    shop_v1_client_free(client);
    return status == shop_v1_ok ? 0 : 1;
}

