example.shop#CountItems.snippet:
#include "shop_v1/client.hpp"

#include <cstdlib>
#include <iostream>

namespace sdk = example::shop_v1;

int main() {
    // The client sends Crucible-Version: v1 on every request.
    sdk::runtime::ClientConfig config;
    if (const char* endpoint = std::getenv("SHOP_ENDPOINT")) config.endpoint = endpoint;
    sdk::ShopClient client(config);

    // Sample values generated from the model's types and constraints.
    const sdk::models::CountItemsInput input("shelf");

    try {
        const auto output = client.count_items(input);
        std::cout << "count: " << sdk::runtime::debug_value(output.count) << '\n';
    } catch (const sdk::models::CountUnavailableException& error) {
        std::cerr << "CountUnavailableException (HTTP " << error.metadata().status << "): " << error.message << '\n';
        return 1;
    }
    return 0;
}

