using System;
using Example.Shop.V1;
using Example.Shop.V1.Models;

// The client sends Crucible-Version: v1 on every request.
using var client = new ShopClient(new ClientConfig
{
    Endpoint = Environment.GetEnvironmentVariable("SHOP_ENDPOINT"),
});

// Sample values generated from the model's types and constraints.
var input = new CountItemsInput
{
    Shelf = "shelf",
};

try
{
    var output = await client.CountItemsAsync(input);
    Console.WriteLine(output.Count);
}
catch (CountUnavailableException error)
{
    Console.Error.WriteLine($"CountUnavailableException (HTTP {error.StatusCode}): {error.MessageValue}");
}

