use shop_sdk::*;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // The client sends Crucible-Version: v1 on every request.
    let client = ShopClient::new(runtime::Config::new(std::env::var("SHOP_ENDPOINT")?));

    // Sample values generated from the model's types and constraints.
    let input = CountItemsInput::builder()
        .shelf("shelf")
        .build();

    match client.count_items(input).await {
        Ok(output) => {
            println!("{:?}", output.count());
        }
        Err(runtime::Error::Service(runtime::ServiceError {
            error: CountItemsError::CountUnavailableException(error),
            metadata,
        })) => {
            eprintln!("CountUnavailableException (HTTP {}): {:?}", metadata.status, error.message());
        }
        Err(error) => return Err(error.into()),
    }
    Ok(())
}

